#!/usr/bin/env pwsh
$basedir=Split-Path $MyInvocation.MyCommand.Definition -Parent

$exe=""
if ($PSVersionTable.PSVersion -lt "6.0" -or $IsWindows) {
  $exe=".exe"
}
$ret=0
if (Test-Path "$basedir//bin/bash$exe") {
  if ($MyInvocation.ExpectingInput) {
    $input | & "$basedir//bin/bash$exe"  "$basedir/../.deno/swc-node@1.0.0/node_modules/swc-node/bin/swc-node" $args
  } else {
    & "$basedir//bin/bash$exe"  "$basedir/../.deno/swc-node@1.0.0/node_modules/swc-node/bin/swc-node" $args
  }
  $ret=$LASTEXITCODE
} else {
  if ($MyInvocation.ExpectingInput) {
    $input | & "/bin/bash$exe"  "$basedir/../.deno/swc-node@1.0.0/node_modules/swc-node/bin/swc-node" $args
  } else {
    & "/bin/bash$exe"  "$basedir/../.deno/swc-node@1.0.0/node_modules/swc-node/bin/swc-node" $args
  }
  $ret=$LASTEXITCODE
}
exit $ret
